// Content with portions generated by generative AI platform
package org.eclipse.kura.internal.rest.auth.jwt;

import static org.junit.Assert.assertEquals;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import org.junit.Test;

import jakarta.ws.rs.core.Response.Status;

public class RefreshTokenReuseDetectionTest extends AbstractRefreshTokenFamilyScenario {

    private static final int OK = Status.OK.getStatusCode();
    private static final int UNAUTHORIZED = Status.UNAUTHORIZED.getStatusCode();
    private static final int CONCURRENT_EXCHANGES = 4;

    private String ownerRefreshToken;
    private String attackerRefreshToken;
    private String secondSessionRefreshToken;
    private int tokensIssuedByTheReplay;

    @Test
    public void replayingAnExchangedRefreshTokenRevokesTheFamily() {
        givenTheOwnerLoggedIn();
        givenTheAttackerExchanged(this.ownerRefreshToken);

        whenTheOwnerExchanges(this.ownerRefreshToken);
        whenTheAttackerExchanges(this.attackerRefreshToken);

        thenTheExchangeStatusesAre(OK, UNAUTHORIZED, UNAUTHORIZED);
    }

    @Test
    public void aReplayedRefreshTokenIsRefusedWithoutIssuingTokens() {
        givenTheOwnerLoggedIn();
        givenTheAttackerExchanged(this.ownerRefreshToken);

        whenTheExchangedRefreshTokenIsReplayed(this.ownerRefreshToken);

        thenTheExchangeStatusesAre(OK, UNAUTHORIZED);
        thenTheReplayIssuedNoTokens();
    }

    @Test
    public void revokingAFamilyLeavesOtherSessionsWorking() {
        givenTheOwnerLoggedIn();
        givenTheOwnerLoggedInASecondSession();
        givenTheAttackerExchanged(this.ownerRefreshToken);
        givenTheOwnerExchanged(this.ownerRefreshToken);

        whenTheSecondSessionExchanges(this.secondSessionRefreshToken);

        thenTheExchangeStatusesAre(OK, UNAUTHORIZED, OK);
    }

    @Test
    public void concurrentExchangesOfTheSameRefreshTokenSucceedOnce() throws Exception {
        givenTheOwnerLoggedIn();
        givenTheIssuerWaitsForAllConcurrentExchanges();

        whenTheRefreshTokenIsExchangedConcurrently(this.ownerRefreshToken);

        thenTheExchangeStatusesAreInAnyOrder(OK, UNAUTHORIZED, UNAUTHORIZED, UNAUTHORIZED);
    }

    private void givenTheOwnerLoggedIn() {
        this.ownerRefreshToken = login().refreshToken();
    }

    private void givenTheOwnerLoggedInASecondSession() {
        this.secondSessionRefreshToken = login().refreshToken();
    }

    private void givenTheAttackerExchanged(final String refreshToken) {
        this.attackerRefreshToken = exchange(refreshToken).orElse(this.attackerRefreshToken);
    }

    private void givenTheOwnerExchanged(final String refreshToken) {
        this.ownerRefreshToken = exchange(refreshToken).orElse(this.ownerRefreshToken);
    }

    private void givenTheIssuerWaitsForAllConcurrentExchanges() {
        // every exchange passes the family check before any of them advances the token family
        holdIssuancesUntilAllStart(CONCURRENT_EXCHANGES);
    }

    private void whenTheOwnerExchanges(final String refreshToken) {
        this.ownerRefreshToken = exchange(refreshToken).orElse(this.ownerRefreshToken);
    }

    private void whenTheExchangedRefreshTokenIsReplayed(final String refreshToken) {
        final int issuedBefore = issuedTokenCount();
        exchange(refreshToken);
        this.tokensIssuedByTheReplay = issuedTokenCount() - issuedBefore;
    }

    private void whenTheSecondSessionExchanges(final String refreshToken) {
        this.secondSessionRefreshToken = exchange(refreshToken).orElse(this.secondSessionRefreshToken);
    }

    private void whenTheAttackerExchanges(final String refreshToken) {
        this.attackerRefreshToken = exchange(refreshToken).orElse(this.attackerRefreshToken);
    }

    private void whenTheRefreshTokenIsExchangedConcurrently(final String refreshToken) throws Exception {
        final ExecutorService executor = Executors.newFixedThreadPool(CONCURRENT_EXCHANGES);

        try {
            final List<Future<?>> exchanges = new ArrayList<>();

            for (int i = 0; i < CONCURRENT_EXCHANGES; i++) {
                exchanges.add(executor.submit(() -> exchange(refreshToken)));
            }

            for (final Future<?> exchange : exchanges) {
                exchange.get(30, TimeUnit.SECONDS);
            }
        } finally {
            executor.shutdownNow();
        }
    }

    private void thenTheReplayIssuedNoTokens() {
        assertEquals(0, this.tokensIssuedByTheReplay);
    }
}
